SELECT * FROM message
WHERE ((from_user_id = #{userId1} AND to_user_id = #{userId2} AND (deleted_by_from_user = 0 OR deleted_by_from_user IS NULL))
   OR (from_user_id = #{userId2} AND to_user_id = #{userId1} AND (deleted_by_to_user = 0 OR deleted_by_to_user IS NULL)))
ORDER BY created_at DESC

    LIMIT #{limit}

        OFFSET #{offset}
